WHERE tenant_id IS NULL AND template_key='tic-report-v1' AND status='active';

INSERT INTO report_rules (tenant_id, template_key, name, version, status, config, created_by, activated_at)
VALUES (NULL, 'tic-report-v1', '江西中标检检测报告（首套版式）', 2, 'active', $config${"name": "江西中标检检测报告（首套版式）", "fields": {"basis": {"labels": ["检验依据", "检测依据", "检验与判定依据"], "pattern": "(?:检验|检测)依据\\s*[:：]?\\s*([^\\n]+)"}, "model": {"labels": ["型号", "型号规格", "规格型号"], "pattern": "(?:型号|规格型号)\\s*[:：]?\\s*([^\\n]+)"}, "remark": {"labels": ["备注"], "pattern": "备注\\s*[:：]?\\s*([^\\n]+)"}, "category": {"labels": ["检验类别", "检测类别"], "pattern": "(?:检验|检测)类别\\s*[:：]?\\s*([^\\n]+)"}, "clientUnit": {"labels": ["委托单位"], "pattern": "委托单位\\s*[:：]?\\s*([^\\n]+)", "required": true}, "conclusion": {"labels": ["检验结论", "检测结论"], "pattern": "(?:检验|检测)结论\\s*[:：]?\\s*([^\\n]+)", "required": true}, "reportDate": {"format": "date", "labels": ["报告日期", "样品完检/报告日期"], "exclude": ["抽样", "送检", "上传", "创建", "打印"], "pattern": "报告日期\\s*[:：]?\\s*([0-9]{4}\\s*[-年/.]\\s*[0-9]{1,2}\\s*[-月/.]\\s*[0-9]{1,2}\\s*日?)", "required": true}, "institution": {"labels": ["检测机构"], "exclude": ["分包"], "pattern": "检测机构\\s*[:：]?\\s*([^\\n]+)", "required": true}, "productName": {"labels": ["产品名称"], "pattern": "产品名称\\s*[:：]?\\s*([^\\n]+)", "required": true}, "manufacturer": {"labels": ["生产单位"], "pattern": "生产单位\\s*[:：]?\\s*([^\\n]+)"}, "reportNumber": {"format": "^[A-Z]{2,6}-[0-9]{6}-[0-9]{3}$", "labels": ["报告编号"], "exclude": ["分包"], "pattern": "报告编号\\s*[:：]?\\s*([A-Za-z0-9-]{6,40})", "required": true}, "inspectedUnit": {"labels": ["受检单位"], "pattern": "受检单位\\s*[:：]?\\s*([^\\n]+)"}}, "details": {"minRows": 1, "endMarkers": ["备注", "以下空白"], "rowPattern": "^(?:[0-9]+[.、]?\\s*)?(?P<item>.+?)\\s+(?P<requirement>[≤≥<>＜＞]?\\s*[0-9]+(?:\\.[0-9]+)?(?:\\s*[~～-]\\s*[0-9.]+)?|不得检出|/)\\s*(?P<unit>%|mg/kg|g/kg|mg/L|g/L|mm|MPa|N|℃|h|min|/)?\\s*(?P<method>(?:GB|HJ|ISO|ASTM|EN|QB|JC)[^\\s]*\\s*[0-9-]*)?\\s*(?P<result>未检出(?:[（(][^）)]*[）)])?|[0-9]+(?:\\.[0-9]+)?)\\s*(?P<judgement>合格|不合格|/)$", "expectedRows": 34, "skipPatterns": ["序号", "技术要求\\s+单位", "第\\s*[0-9]+\\s*页", "共\\s*[0-9]+\\s*页"], "startMarkers": ["检测项目", "检验项目"], "requireFields": ["item", "requirement", "result", "judgement"], "sectionPattern": "^(?P<section>[一二三四五六七八九十]+、[^\\s].*)$", "continuationPattern": "^\\s{2,}(?P<continuation>.+)$"}, "validation": {"requireDetails": true, "requiredFields": ["reportNumber", "productName", "institution", "clientUnit", "reportDate", "conclusion"], "allowEmptyValues": ["/", "—", "-", "无"]}, "institution": "江西中标检检测中心有限公司", "templateKey": "tic-report-v1", "layoutMarkers": ["检测报告", "报告编号", "检验结论", "检测项目"]}$config$::jsonb, 'platform:system', now());
